     1→// 런타임 엔진 (Runtime Engine)
     2→// Phase 5 Stage 2: 런타임 실행
     3→
     4→use crate::value::Value;
     5→use crate::heap::Heap;
     6→use crate::stack::Stack;
     7→use crate::ir::IRNode;
     8→use std::collections::HashMap;
     9→
    10→/// 런타임 에러
    11→#[derive(Debug, Clone, PartialEq)]
    12→pub enum RuntimeError {
    13→    TypeMismatch { expected: String, got: String },
    14→    UndefinedVariable(String),
    15→    UndefinedFunction(String),
    16→    DivisionByZero,
    17→    IndexOutOfBounds { index: i64, length: usize },
    18→    StackOverflow,
    19→    InvalidOperation(String),
    20→    StackUnderflow,
    21→    EmptyReturn,
    22→}
    23→
    24→impl std::fmt::Display for RuntimeError {
    25→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    26→        match self {
    27→            RuntimeError::TypeMismatch { expected, got } => {
    28→                write!(f, "Type mismatch: expected {}, got {}", expected, got)
    29→            }
    30→            RuntimeError::UndefinedVariable(var) => write!(f, "Undefined variable: {}", var),
    31→            RuntimeError::UndefinedFunction(func) => write!(f, "Undefined function: {}", func),
    32→            RuntimeError::DivisionByZero => write!(f, "Division by zero"),
    33→            RuntimeError::IndexOutOfBounds { index, length } => {
    34→                write!(f, "Index out of bounds: {} (length: {})", index, length)
    35→            }
    36→            RuntimeError::StackOverflow => write!(f, "Stack overflow"),
    37→            RuntimeError::InvalidOperation(op) => write!(f, "Invalid operation: {}", op),
    38→            RuntimeError::StackUnderflow => write!(f, "Stack underflow"),
    39→            RuntimeError::EmptyReturn => write!(f, "Empty return value"),
    40→        }
    41→    }
    42→}
    43→
    44→impl std::error::Error for RuntimeError {}
    45→
    46→/// 함수 정보
    47→#[derive(Debug, Clone)]
    48→pub struct FunctionDef {
    49→    pub name: String,
    50→    pub params: Vec<String>,
    51→    pub body: Vec<IRNode>,
    52→}
    53→
    54→/// 런타임 환경
    55→#[derive(Debug, Clone)]
    56→pub struct Runtime {
    57→    /// 힙 메모리
    58→    heap: Heap,
    59→    /// 호출 스택
    60→    stack: Stack,
    61→    /// 프로그램 카운터
    62→    pc: usize,
    63→    /// 정의된 함수들
    64→    functions: HashMap<String, FunctionDef>,
    65→    /// 반환값 저장소
    66→    return_value: Option<Value>,
    67→}
    68→
    69→impl Runtime {
    70→    /// 새 런타임 생성
    71→    pub fn new() -> Self {
    72→        Runtime {
    73→            heap: Heap::new(),
    74→            stack: Stack::new(),
    75→            pc: 0,
    76→            functions: HashMap::new(),
    77→            return_value: None,
    78→        }
    79→    }
    80→
    81→    /// 프로그램 실행
    82→    pub fn execute(&mut self, nodes: &[IRNode]) -> Result<Value, RuntimeError> {
    83→        self.pc = 0;
    84→        self.return_value = None;
    85→
    86→        // 최대 스택 깊이 확인 (오버플로우 방지)
    87→        const MAX_STACK_DEPTH: usize = 1000;
    88→
    89→        for node in nodes {
    90→            if self.stack.depth() > MAX_STACK_DEPTH {
    91→                return Err(RuntimeError::StackOverflow);
    92→            }
    93→
    94→            self.eval_node(node)?;
    95→
    96→            // 반환값이 설정되면 중단
    97→            if self.return_value.is_some() {
    98→                break;
    99→            }
   100→        }
   101→
   102→        // 반환값이 있으면 반환, 없으면 None
   103→        Ok(self.return_value.take().unwrap_or(Value::None))
   104→    }
   105→
   106→    /// 노드 평가
   107→    pub fn eval_node(&mut self, node: &IRNode) -> Result<(), RuntimeError> {
   108→        match node {
   109→            IRNode::Literal { value } => {
   110→                self.return_value = Some(value.clone());
   111→                Ok(())
   112→            }
   113→            IRNode::Variable { name } => {
   114→                let val = self
   115→                    .stack
   116→                    .get_var(name)
   117→                    .ok_or_else(|| RuntimeError::UndefinedVariable(name.clone()))?;
   118→                self.return_value = Some(val);
   119→                Ok(())
   120→            }
   121→            IRNode::Assign { name, value } => {
   122→                self.eval_node(value)?;
   123→                let val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
   124→                self.stack.set_var(name.clone(), val)?;
   125→                self.return_value = Some(Value::None);
   126→                Ok(())
   127→            }
   128→            IRNode::BinaryOp { op, left, right } => {
   129→                self.eval_node(left)?;
   130→                let left_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
   131→
   132→                self.eval_node(right)?;
   133→                let right_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
   134→
   135→                let result = self.eval_binary_op(op, left_val, right_val)?;
   136→                self.return_value = Some(result);
   137→                Ok(())
   138→            }
   139→            IRNode::UnaryOp { op, operand } => {
   140→                self.eval_node(operand)?;
   141→                let val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
   142→                let result = self.eval_unary_op(op, val)?;
   143→                self.return_value = Some(result);
   144→                Ok(())
   145→            }
   146→            IRNode::If { condition, then_branch, else_branch } => {
   147→                self.eval_node(condition)?;
   148→                let cond_val = self.return_value.take().ok_or(RuntimeError::EmptyReturn)?;
   149→
   150→                if cond_val.to_bool() {
   151→                    for node in then_branch {
   152→                        self.eval_node(node)?;
   153→                        if self.return_value.is_some() {
   154→                            break;
   155→                        }
   156→                    }
   157→                } else if let Some(else_nodes) = else_branch {
   158→                    for node in else_nodes {
   159→                        self.eval_node(node)?;
   160→                        if self.return_value.is_some() {
   161→                            break;
   162→                        }
   163→                    }
   164→                } else {
   165→                    self.return_value = Some(Value::None);
   166→                }
   167→                Ok(())
   168→            }
   169→            IRNode::Block { statements } => {
   170→                for node in statements {
   171→                    self.eval_node(node)?;
   172→                }
   173→                Ok(())
   174→            }
   175→            IRNode::Return { value } => {
   176→                if let Some(val) = value {
   177→                    self.eval_node(val)?;
   178→                } else {
   179→                    self.return_value = Some(Value::None);
   180→                }
   181→                Ok(())
   182→            }
   183→            _ => Err(RuntimeError::InvalidOperation(format!("Unsupported node: {:?}", node))),
   184→        }
   185→    }
   186→
   187→    /// 이항 연산 평가
   188→    fn eval_binary_op(
   189→        &self,
   190→        op: &str,
   191→        left: Value,
   192→        right: Value,
   193→    ) -> Result<Value, RuntimeError> {
   194→        match op {
   195→            "+" => self.eval_add(left, right),
   196→            "-" => self.eval_subtract(left, right),
   197→            "*" => self.eval_multiply(left, right),
   198→            "/" => self.eval_divide(left, right),
   199→            "%" => self.eval_modulo(left, right),
   200→            "==" => Ok(Value::Boolean(left.equals(&right))),
   201→            "!=" => Ok(Value::Boolean(!left.equals(&right))),
   202→            "<" => self.eval_less_than(left, right),
   203→            "<=" => self.eval_less_equal(left, right),
   204→            ">" => self.eval_greater_than(left, right),
   205→            ">=" => self.eval_greater_equal(left, right),
   206→            "&&" => Ok(Value::Boolean(left.to_bool() && right.to_bool())),
   207→            "||" => Ok(Value::Boolean(left.to_bool() || right.to_bool())),
   208→            _ => Err(RuntimeError::InvalidOperation(format!("Unknown operator: {}", op))),
   209→        }
   210→    }
   211→
   212→    /// 단항 연산 평가
   213→    fn eval_unary_op(&self, op: &str, operand: Value) -> Result<Value, RuntimeError> {
   214→        match op {
   215→            "-" => match operand {
   216→                Value::Integer(n) => Ok(Value::Integer(-n)),
   217→                Value::Float(f) => Ok(Value::Float(-f)),
   218→                _ => Err(RuntimeError::TypeMismatch {
   219→                    expected: "numeric".to_string(),
   220→                    got: operand.type_name().to_string(),
   221→                }),
   222→            },
   223→            "!" => Ok(Value::Boolean(!operand.to_bool())),
   224→            _ => Err(RuntimeError::InvalidOperation(format!("Unknown unary operator: {}", op))),
   225→        }
   226→    }
   227→
   228→    // 산술 연산
   229→    fn eval_add(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   230→        match (left, right) {
   231→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a + b)),
   232→            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
   233→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 + b)),
   234→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a + b as f64)),
   235→            (Value::String(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
   236→            (left, right) => Err(RuntimeError::TypeMismatch {
   237→                expected: "numeric or string".to_string(),
   238→                got: format!("{} + {}", left.type_name(), right.type_name()),
   239→            }),
   240→        }
   241→    }
   242→
   243→    fn eval_subtract(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   244→        match (left, right) {
   245→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a - b)),
   246→            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
   247→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 - b)),
   248→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a - b as f64)),
   249→            (left, right) => Err(RuntimeError::TypeMismatch {
   250→                expected: "numeric".to_string(),
   251→                got: format!("{} - {}", left.type_name(), right.type_name()),
   252→            }),
   253→        }
   254→    }
   255→
   256→    fn eval_multiply(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   257→        match (left, right) {
   258→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer(a * b)),
   259→            (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
   260→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Float(a as f64 * b)),
   261→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Float(a * b as f64)),
   262→            (left, right) => Err(RuntimeError::TypeMismatch {
   263→                expected: "numeric".to_string(),
   264→                got: format!("{} * {}", left.type_name(), right.type_name()),
   265→            }),
   266→        }
   267→    }
   268→
   269→    fn eval_divide(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   270→        match (left, right) {
   271→            (Value::Integer(a), Value::Integer(b)) => {
   272→                if b == 0 {
   273→                    Err(RuntimeError::DivisionByZero)
   274→                } else {
   275→                    Ok(Value::Integer(a / b))
   276→                }
   277→            }
   278→            (Value::Float(a), Value::Float(b)) => {
   279→                if b == 0.0 {
   280→                    Err(RuntimeError::DivisionByZero)
   281→                } else {
   282→                    Ok(Value::Float(a / b))
   283→                }
   284→            }
   285→            (Value::Integer(a), Value::Float(b)) => {
   286→                if b == 0.0 {
   287→                    Err(RuntimeError::DivisionByZero)
   288→                } else {
   289→                    Ok(Value::Float(a as f64 / b))
   290→                }
   291→            }
   292→            (Value::Float(a), Value::Integer(b)) => {
   293→                if b == 0 {
   294→                    Err(RuntimeError::DivisionByZero)
   295→                } else {
   296→                    Ok(Value::Float(a / b as f64))
   297→                }
   298→            }
   299→            (left, right) => Err(RuntimeError::TypeMismatch {
   300→                expected: "numeric".to_string(),
   301→                got: format!("{} / {}", left.type_name(), right.type_name()),
   302→            }),
   303→        }
   304→    }
   305→
   306→    fn eval_modulo(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   307→        match (left, right) {
   308→            (Value::Integer(a), Value::Integer(b)) => {
   309→                if b == 0 {
   310→                    Err(RuntimeError::DivisionByZero)
   311→                } else {
   312→                    Ok(Value::Integer(a % b))
   313→                }
   314→            }
   315→            (left, right) => Err(RuntimeError::TypeMismatch {
   316→                expected: "integer".to_string(),
   317→                got: format!("{} % {}", left.type_name(), right.type_name()),
   318→            }),
   319→        }
   320→    }
   321→
   322→    // 비교 연산
   323→    fn eval_less_than(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   324→        match (left, right) {
   325→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a < b)),
   326→            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a < b)),
   327→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) < b)),
   328→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a < (b as f64))),
   329→            (left, right) => Err(RuntimeError::TypeMismatch {
   330→                expected: "numeric".to_string(),
   331→                got: format!("{} < {}", left.type_name(), right.type_name()),
   332→            }),
   333→        }
   334→    }
   335→
   336→    fn eval_less_equal(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   337→        match (left, right) {
   338→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a <= b)),
   339→            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a <= b)),
   340→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) <= b)),
   341→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a <= (b as f64))),
   342→            (left, right) => Err(RuntimeError::TypeMismatch {
   343→                expected: "numeric".to_string(),
   344→                got: format!("{} <= {}", left.type_name(), right.type_name()),
   345→            }),
   346→        }
   347→    }
   348→
   349→    fn eval_greater_than(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   350→        match (left, right) {
   351→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a > b)),
   352→            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a > b)),
   353→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) > b)),
   354→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a > (b as f64))),
   355→            (left, right) => Err(RuntimeError::TypeMismatch {
   356→                expected: "numeric".to_string(),
   357→                got: format!("{} > {}", left.type_name(), right.type_name()),
   358→            }),
   359→        }
   360→    }
   361→
   362→    fn eval_greater_equal(&self, left: Value, right: Value) -> Result<Value, RuntimeError> {
   363→        match (left, right) {
   364→            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Boolean(a >= b)),
   365→            (Value::Float(a), Value::Float(b)) => Ok(Value::Boolean(a >= b)),
   366→            (Value::Integer(a), Value::Float(b)) => Ok(Value::Boolean((a as f64) >= b)),
   367→            (Value::Float(a), Value::Integer(b)) => Ok(Value::Boolean(a >= (b as f64))),
   368→            (left, right) => Err(RuntimeError::TypeMismatch {
   369→                expected: "numeric".to_string(),
   370→                got: format!("{} >= {}", left.type_name(), right.type_name()),
   371→            }),
   372→        }
   373→    }
   374→
   375→    pub fn heap(&self) -> &Heap {
   376→        &self.heap
   377→    }
   378→
   379→    pub fn stack(&self) -> &Stack {
   380→        &self.stack
   381→    }
   382→
   383→    pub fn heap_mut(&mut self) -> &mut Heap {
   384→        &mut self.heap
   385→    }
   386→
   387→    pub fn stack_mut(&mut self) -> &mut Stack {
   388→        &mut self.stack
   389→    }
   390→}
   391→
   392→impl Default for Runtime {
   393→    fn default() -> Self {
   394→        Self::new()
   395→    }
   396→}
