   546→    #[test]
   547→    fn test_eval_logical_and() {
   548→        let mut runtime = Runtime::new();
   549→        let left = IRNode::Literal {
   550→            value: Value::Boolean(true),
   551→        };
   552→        let right = IRNode::Literal {
   553→            value: Value::Boolean(false),
   554→        };
   555→        let and = IRNode::BinaryOp {
   556→            op: "&&".to_string(),
   557→            left: Box::new(left),
   558→            right: Box::new(right),
   559→        };
   560→        let result = runtime.execute(&[and]);
   561→        assert_eq!(result, Ok(Value::Boolean(false)));
   562→    }
   563→
   564→    #[test]
   565→    fn test_eval_logical_or() {
   566→        let mut runtime = Runtime::new();
   567→        let left = IRNode::Literal {
