     1→// 컴파일러 통합 (Compiler Integration)
     2→// Phase 5 Stage 3: 완전한 컴파일 파이프라인
     3→
     4→use crate::lexer::Lexer;
     5→use crate::parser::Parser;
     6→use crate::type_checker::TypeChecker;
     7→use crate::codegen::CodeGenerator;
     8→use crate::runtime::{Runtime, RuntimeError};
     9→use crate::value::Value;
    10→
    11→/// 컴파일 에러
    12→#[derive(Debug, Clone)]
    13→pub enum CompileError {
    14→    LexerError(String),
    15→    ParserError(String),
    16→    TypeError(String),
    17→    CodegenError(String),
    18→    RuntimeError(String),
    19→}
    20→
    21→impl std::fmt::Display for CompileError {
    22→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    23→        match self {
    24→            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
    25→            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
    26→            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
    27→            CompileError::CodegenError(e) => write!(f, "Code generation error: {}", e),
    28→            CompileError::RuntimeError(e) => write!(f, "Runtime error: {}", e),
    29→        }
    30→    }
    31→}
    32→
    33→impl std::error::Error for CompileError {}
    34→
    35→impl From<RuntimeError> for CompileError {
    36→    fn from(err: RuntimeError) -> Self {
    37→        CompileError::RuntimeError(err.to_string())
    38→    }
    39→}
    40→
    41→/// 완전한 컴파일러
    42→pub struct Compiler {
    43→    lexer: Lexer,
    44→    parser: Parser,
    45→    type_checker: TypeChecker,
    46→    codegen: CodeGenerator,
    47→    runtime: Runtime,
    48→}
    49→
    50→impl Compiler {
    51→    /// 새 컴파일러 생성
    52→    pub fn new() -> Self {
    53→        Compiler {
    54→            lexer: Lexer::new(""),
    55→            parser: Parser::new(Vec::new()),
    56→            type_checker: TypeChecker::new(),
    57→            codegen: CodeGenerator::new(),
    58→            runtime: Runtime::new(),
    59→        }
    60→    }
    61→
    62→    /// 소스 코드 컴파일 및 실행
    63→    pub fn compile_and_run(&mut self, source: &str) -> Result<Value, CompileError> {
    64→        // Step 1: Lexer (소스 → 토큰)
    65→        let mut lexer = Lexer::new(source);
    66→        let tokens = lexer
    67→            .tokenize()
    68→            .map_err(|e| CompileError::LexerError(e.to_string()))?;
    69→
    70→        // Step 2: Parser (토큰 → AST)
    71→        let parser = Parser::new(tokens);
    72→        let ast = parser
    73→            .parse()
    74→            .map_err(|e| CompileError::ParserError(e.to_string()))?;
    75→
    76→        // Step 3: Type Checker (AST → Typed AST)
    77→        let type_checker = TypeChecker::new();
    78→        let typed_ast = type_checker
    79→            .check(&ast)
    80→            .map_err(|e| CompileError::TypeError(e.to_string()))?;
    81→
    82→        // Step 4: Code Generator (Typed AST → IR)
    83→        let codegen = CodeGenerator::new();
    84→        let ir = codegen
    85→            .ast_to_ir(&typed_ast)
    86→            .map_err(|e| CompileError::CodegenError(e.to_string()))?;
    87→
    88→        // Step 5: Runtime (IR → 실행)
    89→        let result = self.runtime.execute(&ir)?;
    90→
    91→        Ok(result)
    92→    }
    93→
    94→    /// 소스 코드를 IR로 컴파일만 수행 (실행 X)
    95→    pub fn compile(&mut self, source: &str) -> Result<crate::ir::IRProgram, CompileError> {
    96→        // Step 1: Lexer
    97→        let mut lexer = Lexer::new(source);
    98→        let tokens = lexer
    99→            .tokenize()
   100→            .map_err(|e| CompileError::LexerError(e.to_string()))?;
   101→
   102→        // Step 2: Parser
   103→        let parser = Parser::new(tokens);
   104→        let ast = parser
   105→            .parse()
   106→            .map_err(|e| CompileError::ParserError(e.to_string()))?;
   107→
   108→        // Step 3: Type Checker
   109→        let type_checker = TypeChecker::new();
   110→        let typed_ast = type_checker
   111→            .check(&ast)
   112→            .map_err(|e| CompileError::TypeError(e.to_string()))?;
   113→
   114→        // Step 4: Code Generator
   115→        let codegen = CodeGenerator::new();
   116→        let ir = codegen
   117→            .ast_to_ir(&typed_ast)
   118→            .map_err(|e| CompileError::CodegenError(e.to_string()))?;
   119→
   120→        Ok(ir)
   121→    }
   122→
   123→    /// 상세 파이프라인: 각 단계별 결과 반환
   124→    pub fn compile_verbose(
   125→        &mut self,
   126→        source: &str,
   127→    ) -> Result<CompilationResult, CompileError> {
   128→        // Step 1: Lexer
   129→        let mut lexer = Lexer::new(source);
   130→        let tokens = lexer
   131→            .tokenize()
   132→            .map_err(|e| CompileError::LexerError(e.to_string()))?;
   133→
   134→        // Step 2: Parser
   135→        let parser = Parser::new(tokens.clone());
   136→        let ast = parser
   137→            .parse()
   138→            .map_err(|e| CompileError::ParserError(e.to_string()))?;
   139→
   140→        // Step 3: Type Checker
   141→        let type_checker = TypeChecker::new();
   142→        let typed_ast = type_checker
   143→            .check(&ast)
   144→            .map_err(|e| CompileError::TypeError(e.to_string()))?;
   145→
   146→        // Step 4: Code Generator
   147→        let codegen = CodeGenerator::new();
   148→        let ir = codegen
   149→            .ast_to_ir(&typed_ast)
   150→            .map_err(|e| CompileError::CodegenError(e.to_string()))?;
   151→
   152→        Ok(CompilationResult {
   153→            tokens: tokens.len(),
   154→            ast_nodes: 1, // 간단한 추정
   155→            ir_nodes: ir.len(),
   156→            success: true,
   157→        })
   158→    }
   159→
   160→    pub fn runtime(&self) -> &Runtime {
   161→        &self.runtime
   162→    }
   163→
   164→    pub fn runtime_mut(&mut self) -> &mut Runtime {
   165→        &mut self.runtime
   166→    }
   167→}
   168→
   169→impl Default for Compiler {
   170→    fn default() -> Self {
   171→        Self::new()
   172→    }
   173→}
   174→
   175→/// 컴파일 결과 정보
   176→#[derive(Debug, Clone)]
   177→pub struct CompilationResult {
   178→    pub tokens: usize,
   179→    pub ast_nodes: usize,
   180→    pub ir_nodes: usize,
   181→    pub success: bool,
