   188→                "✅ Compilation successful\n  Tokens: {}\n  AST Nodes: {}\n  IR Nodes: {}",
   189→                self.tokens, self.ast_nodes, self.ir_nodes
   190→            )
   191→        } else {
   192→            "❌ Compilation failed".to_string()
   193→        }
   194→    }
   195→}
