     1→// 값 표현 (Value Representation)
     2→// Phase 5: 런타임
     3→
     4→use std::collections::HashMap;
     5→use std::fmt;
     6→use crate::ir::IRNode;
     7→
     8→/// 런타임 값 표현
     9→#[derive(Debug, Clone, PartialEq)]
    10→pub enum Value {
    11→    /// 정수 (64-bit)
    12→    Integer(i64),
    13→
    14→    /// 실수 (64-bit)
    15→    Float(f64),
    16→
    17→    /// 문자열
    18→    String(String),
    19→
    20→    /// 불린
    21→    Boolean(bool),
    22→
    23→    /// 배열
    24→    Array(Vec<Value>),
    25→
    26→    /// 튜플
    27→    Tuple(Vec<Value>),
    28→
    29→    /// 함수
    30→    Function {
    31→        name: String,
    32→        params: Vec<String>,
    33→        body: Vec<IRNode>,
    34→    },
    35→
    36→    /// 빈 값
    37→    None,
    38→}
    39→
    40→impl Value {
    41→    /// 값의 타입 이름을 반환합니다
    42→    pub fn type_name(&self) -> &str {
    43→        match self {
    44→            Value::Integer(_) => "integer",
    45→            Value::Float(_) => "float",
    46→            Value::String(_) => "string",
    47→            Value::Boolean(_) => "boolean",
    48→            Value::Array(_) => "array",
    49→            Value::Tuple(_) => "tuple",
    50→            Value::Function { .. } => "function",
    51→            Value::None => "none",
    52→        }
    53→    }
    54→
    55→    /// 값을 정수로 변환합니다
    56→    pub fn to_integer(&self) -> Option<i64> {
    57→        match self {
    58→            Value::Integer(n) => Some(*n),
    59→            Value::Float(f) => Some(*f as i64),
    60→            Value::Boolean(b) => Some(if *b { 1 } else { 0 }),
    61→            _ => None,
    62→        }
    63→    }
    64→
    65→    /// 값을 실수로 변환합니다
    66→    pub fn to_float(&self) -> Option<f64> {
    67→        match self {
    68→            Value::Integer(n) => Some(*n as f64),
    69→            Value::Float(f) => Some(*f),
    70→            Value::Boolean(b) => Some(if *b { 1.0 } else { 0.0 }),
    71→            _ => None,
    72→        }
    73→    }
    74→
    75→    /// 값을 문자열로 변환합니다
    76→    pub fn to_string(&self) -> String {
    77→        match self {
    78→            Value::Integer(n) => n.to_string(),
    79→            Value::Float(f) => f.to_string(),
    80→            Value::String(s) => s.clone(),
    81→            Value::Boolean(b) => b.to_string(),
    82→            Value::Array(arr) => {
    83→                let items: Vec<String> = arr.iter().map(|v| v.to_string()).collect();
    84→                format!("[{}]", items.join(", "))
    85→            }
    86→            Value::Tuple(tuple) => {
    87→                let items: Vec<String> = tuple.iter().map(|v| v.to_string()).collect();
    88→                format!("({})", items.join(", "))
    89→            }
    90→            Value::Function { name, .. } => format!("<fn {}>", name),
    91→            Value::None => "none".to_string(),
    92→        }
    93→    }
    94→
    95→    /// 값을 불린으로 변환합니다
    96→    pub fn to_bool(&self) -> bool {
    97→        match self {
    98→            Value::Boolean(b) => *b,
    99→            Value::Integer(n) => *n != 0,
   100→            Value::Float(f) => *f != 0.0,
   101→            Value::String(s) => !s.is_empty(),
   102→            Value::Array(a) => !a.is_empty(),
   103→            Value::None => false,
   104→            _ => true,
   105→        }
   106→    }
   107→
   108→    /// 값이 같은지 비교합니다
   109→    pub fn equals(&self, other: &Value) -> bool {
   110→        match (self, other) {
   111→            (Value::Integer(a), Value::Integer(b)) => a == b,
   112→            (Value::Float(a), Value::Float(b)) => a == b,
   113→            (Value::String(a), Value::String(b)) => a == b,
   114→            (Value::Boolean(a), Value::Boolean(b)) => a == b,
   115→            (Value::None, Value::None) => true,
   116→            // 다른 타입 간 비교
   117→            (Value::Integer(a), Value::Float(b)) => *a as f64 == *b,
   118→            (Value::Float(a), Value::Integer(b)) => *a == *b as f64,
   119→            _ => false,
   120→        }
   121→    }
   122→
   123→    /// 배열 인덱스 접근
   124→    pub fn get_index(&self, index: usize) -> Option<Value> {
   125→        match self {
   126→            Value::Array(arr) => arr.get(index).cloned(),
   127→            Value::String(s) => {
   128→                s.chars()
   129→                    .nth(index)
   130→                    .map(|c| Value::String(c.to_string()))
   131→            }
   132→            Value::Tuple(t) => t.get(index).cloned(),
   133→            _ => None,
   134→        }
   135→    }
   136→
   137→    /// 배열 길이 반환
   138→    pub fn len(&self) -> Option<usize> {
   139→        match self {
   140→            Value::Array(arr) => Some(arr.len()),
   141→            Value::String(s) => Some(s.len()),
   142→            Value::Tuple(t) => Some(t.len()),
   143→            _ => None,
   144→        }
   145→    }
   146→
   147→    /// 배열에 요소 추가
   148→    pub fn push(&mut self, value: Value) -> Result<(), String> {
   149→        match self {
   150→            Value::Array(arr) => {
   151→                arr.push(value);
   152→                Ok(())
   153→            }
   154→            _ => Err(format!("Cannot push to {}", self.type_name())),
   155→        }
   156→    }
   157→}
   158→
   159→impl fmt::Display for Value {
   160→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   161→        write!(f, "{}", self.to_string())
   162→    }
   163→}
