     1→// 힙 메모리 관리 (Heap Memory Management)
     2→// Phase 5: 런타임
     3→
     4→use crate::value::Value;
     5→
     6→/// 힙 메모리 관리자
     7→#[derive(Debug, Clone)]
     8→pub struct Heap {
     9→    /// 메모리 저장소
    10→    memory: Vec<Value>,
    11→    /// 해제된 블록 (재사용 리스트)
    12→    free_list: Vec<usize>,
    13→}
    14→
    15→impl Heap {
    16→    /// 새 힙 생성
    17→    pub fn new() -> Self {
    18→        Heap {
    19→            memory: Vec::new(),
    20→            free_list: Vec::new(),
    21→        }
    22→    }
    23→
    24→    /// 메모리 할당
    25→    /// 새로운 값을 힙에 할당하고 주소를 반환합니다
    26→    pub fn allocate(&mut self, value: Value) -> usize {
    27→        // 해제된 블록이 있으면 재사용
    28→        if let Some(addr) = self.free_list.pop() {
    29→            self.memory[addr] = value;
    30→            addr
    31→        } else {
    32→            // 새 메모리 할당
    33→            let addr = self.memory.len();
    34→            self.memory.push(value);
    35→            addr
    36→        }
    37→    }
    38→
    39→    /// 메모리 해제
    40→    /// 주소의 값을 제거하고 블록을 해제 목록에 추가합니다
    41→    pub fn deallocate(&mut self, addr: usize) -> Result<(), String> {
    42→        if addr >= self.memory.len() {
    43→            return Err(format!("Invalid address: {}", addr));
    44→        }
    45→        self.free_list.push(addr);
    46→        Ok(())
    47→    }
    48→
    49→    /// 메모리에서 값 읽기
    50→    pub fn get(&self, addr: usize) -> Result<&Value, String> {
    51→        if addr >= self.memory.len() {
    52→            return Err(format!("Invalid address: {}", addr));
    53→        }
    54→        Ok(&self.memory[addr])
    55→    }
    56→
    57→    /// 메모리에 값 쓰기
    58→    pub fn set(&mut self, addr: usize, value: Value) -> Result<(), String> {
    59→        if addr >= self.memory.len() {
    60→            return Err(format!("Invalid address: {}", addr));
    61→        }
    62→        self.memory[addr] = value;
    63→        Ok(())
    64→    }
    65→
    66→    /// 힙 크기 (할당된 블록 수)
    67→    pub fn size(&self) -> usize {
    68→        self.memory.len()
    69→    }
    70→
    71→    /// 해제된 블록 수
    72→    pub fn free_count(&self) -> usize {
    73→        self.free_list.len()
    74→    }
    75→
    76→    /// 힙 초기화
    77→    pub fn clear(&mut self) {
    78→        self.memory.clear();
    79→        self.free_list.clear();
    80→    }
