     1→// FV-Lang (Free Value Language)
     2→// A functional-first programming language with strong type inference
     3→//
     4→// This library provides the core compiler infrastructure:
     5→// - Lexer: Tokenization
     6→// - Parser: Abstract Syntax Tree construction
     7→// - Type System: Type inference and checking
     8→// - Code Generator: Compilation to IR/Native code
     9→
    10→pub mod lexer;
    11→pub mod parser;
    12→pub mod ast;
    13→pub mod types;
    14→pub mod symbols;
    15→pub mod type_checker;
    16→pub mod ir;
    17→pub mod codegen;
    18→pub mod value;
    19→pub mod heap;
    20→pub mod stack;
    21→pub mod runtime;
    22→pub mod compiler;
    23→pub mod stdlib;
    24→
    25→pub use lexer::Lexer;
    26→pub use parser::Parser;
    27→pub use ast::Program;
    28→pub use types::Type;
    29→pub use symbols::SymbolTable;
    30→pub use type_checker::{TypeChecker, TypeError};
    31→pub use codegen::CodeGenerator;
    32→pub use value::Value;
    33→pub use heap::Heap;
    34→pub use stack::{Stack, StackFrame};
    35→pub use runtime::{Runtime, RuntimeError};
    36→pub use compiler::{Compiler, CompileError, CompilationResult};
    37→
    38→/// Compile FV-Lang source code to executable
    39→pub fn compile(source: &str) -> Result<String, CompileError> {
    40→    // Lexer: Source → Tokens
    41→    let lexer = Lexer::new(source);
    42→    let tokens = lexer.tokenize()?;
    43→
    44→    // Parser: Tokens → AST
    45→    let parser = Parser::new(tokens);
    46→    let ast = parser.parse()?;
    47→
    48→    // Type Checker: AST → Typed AST
    49→    let type_checker = TypeChecker::new();
    50→    let typed_ast = type_checker.check(&ast)?;
    51→
    52→    // Code Generator: Typed AST → IR/Native Code
    53→    let codegen = CodeGenerator::new();
    54→    let code = codegen.generate(&typed_ast)?;
    55→
    56→    Ok(code)
    57→}
    58→
    59→#[derive(Debug, Clone)]
    60→pub enum CompileError {
    61→    LexerError(String),
    62→    ParserError(String),
    63→    TypeError(String),
    64→    GenerationError(String),
    65→}
    66→
    67→impl std::fmt::Display for CompileError {
    68→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    69→        match self {
    70→            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
    71→            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
    72→            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
    73→            CompileError::GenerationError(e) => write!(f, "Generation error: {}", e),
    74→        }
    75→    }
    76→}
    77→
    78→impl std::error::Error for CompileError {}
    79→

